css:
.venturelysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #14302a;
    background: linear-gradient(170deg, #f4fbf6 0%, #eafaf1 45%, #e3f5ef 100%);
    border-radius: 18px;
}

.venturelysim-container * {
    box-sizing: border-box;
}

.venturelysim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #0f7a52 0%, #16a06b 55%, #2bc4a0 100%);
    color: #f3fff9;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 14px 34px rgba(15, 122, 82, 0.28);
}

.venturelysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.venturelysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #eafff5;
    background: rgba(255, 255, 255, 0.18);
    border: 1px solid rgba(255, 255, 255, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.venturelysim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7fff5;
}

.venturelysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3a6256;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.venturelysim-period-counter #currentDay,
.venturelysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f7a52;
}

.venturelysim-round-name {
    background: rgba(15, 122, 82, 0.12);
    color: #0f7a52;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.venturelysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b15600;
    background: rgba(243, 156, 18, 0.16);
    border: 1px solid rgba(243, 156, 18, 0.40);
    padding: 4px 12px;
    border-radius: 999px;
}

.venturelysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.venturelysim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d7ecdf;
    box-shadow: 0 6px 16px rgba(20, 48, 42, 0.07);
    border-top: 4px solid #16a06b;
}

.venturelysim-card-runway { border-top-color: #f39c12; }
.venturelysim-card-ratio { border-top-color: #0f7a52; }
.venturelysim-card-confidence { border-top-color: #2563d9; }
.venturelysim-card-moat { border-top-color: #8a4fff; }

.venturelysim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b8a7f;
}

.venturelysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14302a;
    font-variant-numeric: tabular-nums;
}

.venturelysim-card-runway .venturelysim-value { color: #d9820a; }
.venturelysim-card-ratio .venturelysim-value { color: #0f7a52; }
.venturelysim-card-confidence .venturelysim-value { color: #2563d9; }
.venturelysim-card-moat .venturelysim-value { color: #8a4fff; }

.venturelysim-sublabel {
    font-size: 0.76rem;
    color: #7a958b;
    line-height: 1.35;
}

.venturelysim-runway-critical { border-top-color: #e23b3b; }
.venturelysim-runway-critical .venturelysim-value { color: #e23b3b; }
.venturelysim-runway-healthy { border-top-color: #16a06b; }
.venturelysim-runway-healthy .venturelysim-value { color: #16a06b; }

.venturelysim-ratio-good { border-top-color: #16a06b; }
.venturelysim-ratio-good .venturelysim-value { color: #16a06b; }
.venturelysim-ratio-bad { border-top-color: #e23b3b; }
.venturelysim-ratio-bad .venturelysim-value { color: #e23b3b; }

.venturelysim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #d7ecdf;
    color: #2d4f45;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.venturelysim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #0f7a52;
}

.venturelysim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #16a06b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 48, 42, 0.07);
}

.venturelysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.venturelysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0f7a52;
    margin-bottom: 6px;
}

.venturelysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #355248;
}

.venturelysim-briefing-text strong { color: #0f7a52; }
.venturelysim-briefing-text em { color: #b15600; font-style: italic; }

.venturelysim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d7ecdf;
    box-shadow: 0 6px 16px rgba(20, 48, 42, 0.07);
}

.venturelysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14302a;
    border-bottom: 2px solid #e1f0e8;
    padding-bottom: 8px;
}

.venturelysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2d4f45;
    margin: 14px 0 6px;
}

.venturelysim-container select,
.venturelysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bfe0cd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6fdf9;
    color: #14302a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.venturelysim-container select:focus,
.venturelysim-container input[type="number"]:focus {
    outline: none;
    border-color: #16a06b;
    box-shadow: 0 0 0 3px rgba(22, 160, 107, 0.18);
}

.venturelysim-container select option {
    background-color: #ffffff;
    color: #14302a;
}

.venturelysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #16a06b;
}

.venturelysim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #3a6256;
    margin-top: 4px;
}

.venturelysim-range-readout span:nth-child(2) {
    color: #0f7a52;
    font-weight: 800;
}

.venturelysim-hint {
    font-size: 0.8rem;
    color: #7a958b;
    margin-top: 4px;
    line-height: 1.4;
}

.venturelysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.venturelysim-container .btn-primary {
    background: linear-gradient(135deg, #0f7a52 0%, #2bc4a0 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(15, 122, 82, 0.30);
}

.venturelysim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.venturelysim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #bfe0cd;
    color: #3a6256;
    background: transparent;
}

.venturelysim-coach {
    background: linear-gradient(160deg, #0f3d2e 0%, #134f3a 100%);
    color: #e7fff5;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(15, 61, 46, 0.25);
}

.venturelysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #5fe0a8;
    margin-bottom: 8px;
}

.venturelysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.venturelysim-coach-body strong { color: #5fe0a8; }
.venturelysim-coach-body em { color: #ffd27a; font-style: italic; }

.venturelysim-history,
.venturelysim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d7ecdf;
    box-shadow: 0 6px 16px rgba(20, 48, 42, 0.07);
}

.venturelysim-history h3,
.venturelysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14302a;
}

.venturelysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2d4f45;
}

.venturelysim-container table#usfHistoryTable th {
    background: #eafaf1;
    color: #0f7a52;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #cdeada;
}

.venturelysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e6f3ec;
    color: #355248;
}

.venturelysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6fdf9;
}

.venturelysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .venturelysim-container {
        padding: 14px;
    }
    .venturelysim-header h1 {
        font-size: 1.7rem;
    }
    .venturelysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .venturelysim-value {
        font-size: 2rem;
    }
    .venturelysim-clock {
        margin-left: 0;
    }
    .venturelysim-period-counter {
        font-size: 0.88rem;
    }
    .venturelysim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .venturelysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ── v1.1.0 completion scorecard (append-only, namespaced .ven-cm-*, startup indigo/cyan) ── */
.ven-cm { margin-top: 8px; }
.ven-cm-incomplete { text-align: center; color: #5b6172; font-size: 1rem; padding: 18px; }
.ven-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.ven-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #26308f 0%, #3d5bd6 55%, #17b6c9 140%); color: #fff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(38,48,143,0.28); }
.ven-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.ven-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.ven-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #bfe6ee; }
.ven-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #fff; border: 1px solid #dde0ee; border-left: 5px solid #3d5bd6; border-radius: 14px; padding: 16px 20px; }
.ven-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5b6172; }
.ven-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #26308f; line-height: 1.15; }
.ven-cm-section { margin-bottom: 16px; }
.ven-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5b6172; margin-bottom: 8px; }
.ven-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.ven-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.ven-cm-ok { background: #e7f0fb; color: #1f4fb0; border-color: #b5cef0; }
.ven-cm-no { background: #fbecec; color: #a5322b; border-color: #eec2be; }
.ven-cm-ico { font-weight: 800; }
.ven-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.ven-cm-kpi { background: #f4f6fd; border: 1px solid #dee3f2; border-radius: 12px; padding: 12px 14px; text-align: center; }
.ven-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #26308f; }
.ven-cm-kpi-lbl { margin-top: 2px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.5px; font-weight: 700; color: #5b6172; }
.ven-cm-kpi-sub { margin-top: 2px; font-size: 0.68rem; color: #8890a5; }
.ven-cm-insights { margin: 0; padding-left: 18px; }
.ven-cm-insights li { font-size: 0.9rem; color: #333a48; margin-bottom: 6px; line-height: 1.45; }

