(function() {
    'use strict';

    class VenturelyAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Model the Future`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Venturely Urban, Lda. — Lisbon, EUR).
            this.START_RUNWAY = 9;       // ~9 months of cash
            this.START_RATIO = 1.2;      // LTV €41 / CAC €34 = 1.2x
            this.TARGET_RATIO = 3.0;     // investor expectation
            this.BURN = 220;             // €220K / month
            this.ARR = 1.4;             // €1.4M ARR
            this.SERIES_A = 6.0;         // €6M raise
            this.AI_FULL = 45;           // ~€45K / month full GenAI deployment
            this.CAC = 34;               // blended CAC €34
            this.LTV = 41;               // LTV €41

            // Concept truths (the coherent winning thread).
            this.TRUE_DIAGNOSIS = `economics`;
            this.TRUE_UNPRICED = `cities`;
            this.TRUE_MODEL = `saas`;        // B2B city SaaS/data — strong margin & retention
            this.TRUE_USECASE = `ops`;       // AI on the task cities pay for
            this.TRUE_POSITION = `data`;     // preferred data partner to cities
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    runway: 9,           // months of cash left
                    ratio: 1.2,          // LTV/CAC ratio
                    confidence: 25,      // investor confidence (0–100)
                    moat: 20,            // ecosystem moat (0–100)
                    budgetUsed: 0,       // €M of the €6M use-of-funds committed
                    model: ``,           // chosen model (set in R2)
                    aiOverspent: false,
                    incoherent: false,
                    runwayHistory: [9],
                    ratioHistory: [1.2],
                    confidenceHistory: [25],
                    moatHistory: [20],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    diagnosis: `economics`,
                    unpriced: `cities`,
                    target: 1.5,
                    model: `consumer`,
                    pricing: `freemium`,
                    invest: 50,
                    usecase: `everywhere`,
                    buildbuy: `buy`,
                    spend: 25,
                    position: `aggregator`,
                    wedge: `wait`,
                    coherence: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagnosisInput`);
                const up = document.getElementById(`unpricedInput`);
                const tg = document.getElementById(`targetInput`);
                if (dg) decisions.diagnosis = dg.value;
                if (up) decisions.unpriced = up.value;
                if (tg) decisions.target = parseFloat(tg.value);
                if (!Number.isFinite(decisions.target) || decisions.target < 1 || decisions.target > 5) {
                    warn(`warn_target_range`); return false;
                }
            } else if (round === 2) {
                const md = document.getElementById(`modelInput`);
                const pr = document.getElementById(`pricingInput`);
                const iv = document.getElementById(`investInput`);
                if (md) decisions.model = md.value;
                if (pr) decisions.pricing = pr.value;
                if (iv) decisions.invest = parseInt(iv.value, 10);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0 || decisions.invest > 100) {
                    warn(`warn_invest_range`); return false;
                }
            } else if (round === 3) {
                const uc = document.getElementById(`usecaseInput`);
                const bb = document.getElementById(`buildbuyInput`);
                const sp = document.getElementById(`spendInput`);
                if (uc) decisions.usecase = uc.value;
                if (bb) decisions.buildbuy = bb.value;
                if (sp) decisions.spend = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.spend) || decisions.spend < 0 || decisions.spend > 45) {
                    warn(`warn_spend_range`); return false;
                }
            } else if (round === 4) {
                const po = document.getElementById(`positionInput`);
                const wd = document.getElementById(`wedgeInput`);
                const ch = document.getElementById(`coherenceInput`);
                if (po) decisions.position = po.value;
                if (wd) decisions.wedge = wd.value;
                if (ch) decisions.coherence = parseInt(ch.value, 10);
                if (!Number.isFinite(decisions.coherence) || decisions.coherence < 0 || decisions.coherence > 100) {
                    warn(`warn_coherence_range`); return false;
                }
            }
            return true;
        }

        _composite(ds) {
            // v1.1.0 — verbatim v1.0.0 composite, extracted so calculateResults and getPerformanceSummary agree.
            const runway = ds.runway;
            const ratio = ds.ratio;
            const confidence = Math.round(ds.confidence);
            const moat = Math.round(ds.moat);
            const ratioScore = Math.max(0, Math.min(100, (ratio / this.TARGET_RATIO) * 100));
            const runwayScore = Math.max(0, Math.min(100, (runway / 12) * 100));
            return Math.round(
                ratioScore * 0.30 + confidence * 0.30 + moat * 0.25 + runwayScore * 0.15
            );
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let runwayDelta = 0, ratioDelta = 0, confidenceDelta = 0, moatDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the model & unit economics (Common Error 1: growth over economics).
                switch (d.diagnosis) {
                    case `economics`: confidenceDelta += 12; moatDelta += 2; coachKey = `coach_r1_economics`; break;
                    case `marketing`: confidenceDelta -= 6; coachKey = `coach_r1_marketing`; break;
                    case `product`: confidenceDelta -= 2; coachKey = `coach_r1_product`; break;
                    case `runway`: confidenceDelta -= 10; coachKey = `coach_r1_runway`; break;
                }

                // Where sustainable value is unpriced (Common Error 2: sustainability as cost/PR).
                switch (d.unpriced) {
                    case `cities`: confidenceDelta += 8; moatDelta += 6; if (d.diagnosis === `economics`) coachKey = `coach_r1_sharp`; break;
                    case `consumers`: confidenceDelta -= 2; coachKey = `coach_r1_greenpremium`; break;
                    case `brand`: confidenceDelta -= 6; moatDelta -= 4; coachKey = `coach_r1_brand`; break;
                    case `none`: confidenceDelta -= 8; coachKey = `coach_r1_none`; break;
                }

                // The LTV/CAC target you commit to (credibility on the gap to 3.0x).
                if (d.target >= 2.8 && d.target <= 3.6) { confidenceDelta += 6; }
                else if (d.target < 1.5) { confidenceDelta -= 6; coachKey = `coach_r1_lowtarget`; }
                else if (d.target >= 4.5) { confidenceDelta -= 5; coachKey = `coach_r1_hightarget`; }

                summaryKey = (d.diagnosis === `economics` && d.unpriced === `cities`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose & design the model (Common Error 4: refusing to choose; Error 1: growth over economics).
                ds.model = d.model;
                const focus = d.invest / 100;

                if (d.model === `everything`) {
                    // Spreading across all three reaches scale in none and signals confusion.
                    confidenceDelta -= 12; moatDelta -= 6; ratioDelta += 0.1; coachKey = `coach_r2_everything`;
                    ds.incoherent = true;
                } else if (d.model === `consumer`) {
                    // Big TAM, weak economics & moat — scaling a 1.2x model accelerates the burn.
                    confidenceDelta -= 4; moatDelta -= 2;
                    ratioDelta += 0.2 - focus * 0.4;   // concentrating capital here makes economics WORSE
                    runwayDelta -= focus * 1.5;        // acquisition burn shortens runway
                    coachKey = `coach_r2_consumer`;
                } else if (d.model === `saas`) {
                    // B2B city SaaS/data — strong margin & retention; the defensible economics play.
                    confidenceDelta += 10; moatDelta += 8;
                    ratioDelta += 0.6 + focus * 1.0;
                    runwayDelta += focus * 0.8;        // higher-margin revenue extends runway
                    coachKey = `coach_r2_saas`;
                } else if (d.model === `platform`) {
                    // Ecosystem/platform — powerful network effects but needs scale (chicken & egg).
                    confidenceDelta += 4; moatDelta += 10;
                    ratioDelta += 0.3 + focus * 0.5;
                    runwayDelta -= (1 - focus) * 1.0;  // under-funding the platform leaves it sub-scale
                    coachKey = `coach_r2_platform`;
                }

                // Reset the revenue mechanic — how sustainable value is priced (Bohnsack reinforcement).
                switch (d.pricing) {
                    case `outcomes`: ratioDelta += 0.9; confidenceDelta += 8; moatDelta += 5; break;
                    case `freemium`: ratioDelta += 0.2; confidenceDelta += 1; break;
                    case `ads`: ratioDelta -= 0.1; confidenceDelta -= 4; moatDelta -= 2; coachKey = `coach_r2_ads`; break;
                    case `unchanged`: ratioDelta -= 0.2; confidenceDelta -= 8; coachKey = `coach_r2_unchanged`; break;
                }

                // Concentrating capital on ONE model is the focus signal investors reward.
                if (d.model !== `everything`) {
                    if (focus >= 0.6) { confidenceDelta += 5; }
                    else if (focus <= 0.3) { confidenceDelta -= 5; coachKey = `coach_r2_unfocused`; }
                }

                summaryKey = (d.model === `saas` && d.pricing === `outcomes`) ? `sum_r2_good` :
                             (d.model === `everything` ? `sum_r2_confused` : `sum_r2_weak`);
            } else if (round === 3) {
                // Deploy generative AI — value driver, not slogan (Common Error 3: AI everywhere).
                const aiCost = d.spend;                 // €K/month committed to AI
                // AI cost burns runway proportionally (full €45K = ~20% of €220K burn).
                runwayDelta -= (aiCost / this.BURN) * (this.START_RUNWAY * 0.55);

                switch (d.usecase) {
                    case `ops`:
                        // Automating municipal reporting — a task cities PAY for: margin + B2B wins.
                        confidenceDelta += 10; ratioDelta += 0.5; moatDelta += 6;
                        if (ds.model === `saas`) { confidenceDelta += 4; ratioDelta += 0.3; coachKey = `coach_r3_ops_fit`; }
                        else { coachKey = `coach_r3_ops`; }
                        break;
                    case `consumer`:
                        // Engagement that is hard to monetise — pays back little against the cost.
                        confidenceDelta += 1; moatDelta += 1; coachKey = `coach_r3_consumer`;
                        break;
                    case `everywhere`:
                        // AI in every surface for ~€45K with nothing it monetises — pure runway leak.
                        confidenceDelta -= 8; ds.aiOverspent = true; coachKey = `coach_r3_everywhere`;
                        break;
                    case `notnow`:
                        // Protects runway but forgoes the one use-case cities pay for.
                        confidenceDelta -= 2; runwayDelta += (aiCost / this.BURN) * (this.START_RUNWAY * 0.55);
                        coachKey = `coach_r3_notnow`;
                        break;
                }

                // Over-spending on AI without a paying use-case is the classic burn (flag at high spend off-ops).
                if (aiCost >= 35 && d.usecase !== `ops`) { ds.aiOverspent = true; runwayDelta -= 0.5; if (coachKey === `coach_default`) coachKey = `coach_r3_overspend`; }

                // Build vs buy — start cheap and validate ROI before committing scarce runway.
                switch (d.buildbuy) {
                    case `buy`: ratioDelta += 0.1; if (d.usecase !== `notnow`) confidenceDelta += 3; break;
                    case `finetune`: moatDelta += 4; confidenceDelta += 2; if (ds.model === `saas` && d.usecase === `ops`) { moatDelta += 3; ratioDelta += 0.2; } break;
                    case `inhouse`: runwayDelta -= 1.0; confidenceDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r3_inhouse` : coachKey; break;
                }

                summaryKey = (d.usecase === `ops` && d.spend <= 30) ? `sum_r3_good` :
                             (d.usecase === `everywhere` || ds.aiOverspent ? `sum_r3_leak` : `sum_r3_weak`);
            } else if (round === 4) {
                // Position in the ecosystem & pitch the raise (Common Errors 4 & 5).
                switch (d.position) {
                    case `data`:
                        // Preferred data/insights partner — the defensible, monetisable wedge for a B2B model.
                        moatDelta += 12; confidenceDelta += 8;
                        if (ds.model === `saas`) { moatDelta += 4; confidenceDelta += 4; coachKey = `coach_r4_data_fit`; }
                        else { coachKey = `coach_r4_data`; }
                        break;
                    case `hub`:
                        // Integration hub — strong network effects for a platform model, needs both sides.
                        moatDelta += 10; confidenceDelta += 5;
                        if (ds.model === `platform`) { moatDelta += 4; coachKey = `coach_r4_hub_fit`; }
                        else { coachKey = `coach_r4_hub`; }
                        break;
                    case `aggregator`:
                        // Consumer aggregator — head-on with the super-app on its own turf: low moat.
                        moatDelta -= 8; confidenceDelta -= 6; coachKey = `coach_r4_aggregator`;
                        break;
                }

                // The wedge to scale before the super-app (chicken-and-egg / timing of platform strategy).
                switch (d.wedge) {
                    case `pilot`: moatDelta += 8; confidenceDelta += 6; break;
                    case `discount`: runwayDelta -= 1.5; moatDelta -= 4; confidenceDelta -= 4; coachKey = `coach_r4_discount`; break;
                    case `wait`: moatDelta -= 8; confidenceDelta -= 6; coachKey = `coach_r4_wait`; break;
                }

                // Coherence across model, AI plan and position — the one-story test.
                const coherentThread = (ds.model === this.TRUE_MODEL && d.position === this.TRUE_POSITION);
                if (d.coherence >= 60 && coherentThread) {
                    confidenceDelta += 14; moatDelta += 4; coachKey = `coach_r4_coherent`;
                } else if (d.coherence >= 60 && !coherentThread) {
                    // High stated coherence but the pieces don't actually fit — investor pulls the thread.
                    confidenceDelta -= 6; ds.incoherent = true; coachKey = `coach_r4_falsecoherence`;
                } else if (d.coherence <= 25) {
                    confidenceDelta -= 8; ds.incoherent = true; coachKey = `coach_r4_incoherent`;
                }

                summaryKey = (d.position === `data` && d.wedge === `pilot` && coherentThread && d.coherence >= 60) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting: meter the €6M Series A use-of-funds across the rounds.
            if (round === 2) { spend += (d.model === `everything`) ? 4.5 : 2.5; }   // GTM concentration
            if (round === 3) { spend += Math.round((d.spend / this.AI_FULL) * 2.0 * 10) / 10; } // AI as % of full deployment
            if (round === 4) { spend += (d.wedge === `discount`) ? 2.5 : 1.5; }     // ecosystem land
            ds.budgetUsed = Math.min(this.SERIES_A, Math.round((ds.budgetUsed + spend) * 10) / 10);

            // Apply deltas, clamped. Runway can go critical; ratio floored at 0; 0–100 indices.
            ds.runway = Math.max(0, Math.round((ds.runway + runwayDelta) * 10) / 10);
            ds.ratio = Math.max(0, Math.round((ds.ratio + ratioDelta) * 100) / 100);
            ds.confidence = Math.max(0, Math.min(100, Math.round(ds.confidence + confidenceDelta)));
            ds.moat = Math.max(0, Math.min(100, Math.round(ds.moat + moatDelta)));

            ds.runwayHistory.push(ds.runway);
            ds.ratioHistory.push(ds.ratio);
            ds.confidenceHistory.push(ds.confidence);
            ds.moatHistory.push(ds.moat);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // v1.1.0 — persist the composite where the gradebook reads it (was never written).
            const _score = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = _score;
            ds.score = _score;

            return {
                period: state.currentPeriod,
                score: _score,
                overallScore: _score,
                runway: ds.runway,
                runwayDelta: Math.round(runwayDelta * 10) / 10,
                ratio: ds.ratio,
                ratioDelta: Math.round(ratioDelta * 100) / 100,
                confidence: ds.confidence,
                confidenceDelta: Math.round(confidenceDelta),
                moat: ds.moat,
                moatDelta: Math.round(moatDelta),
                budgetUsed: ds.budgetUsed,
                aiOverspent: ds.aiOverspent,
                incoherent: ds.incoherent,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoneyM(v) {
            // Locale-aware EUR (millions): English "€6.0M", Spanish "6,0 M€".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(1).replace(`.`, `,`)} M€`;
            }
            return `${sign}€${abs.toFixed(1)}M`;
        }

        _fmtRatio(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const num = Number(v).toFixed(1);
            return (lang === `es` ? num.replace(`.`, `,`) : num) + `x`;
        }

        _fmtMonths(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const num = Number(v).toFixed(1);
            return lang === `es` ? num.replace(`.`, `,`) : num;
        }

