        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const runway = ds.runway;
            const ratio = ds.ratio;
            const confidence = Math.round(ds.confidence);
            const moat = Math.round(ds.moat);

            // v1.1.0 — reuse the shared helper so completion composite == final period's persisted score.
            const composite = this._composite(ds);

            const fundable = ratio >= this.TARGET_RATIO && confidence >= 60;
            const solvent = runway >= 6;
            const defensible = moat >= 60;
            const incoherent = ds.incoherent || (confidence < 45 && ratio < 2.0);

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = `grade_lapsed`;
            if (fundable && solvent && defensible && composite >= 75) tierKey = `grade_closed`;
            else if (fundable && solvent) tierKey = `grade_fundable`;
            else if (ds.aiOverspent && runway < 5) tierKey = `grade_aiburn`;
            else if (incoherent) tierKey = `grade_incoherent`;
            else if (composite >= 55) tierKey = `grade_mixed`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (fundable && solvent && defensible) insights.push(window.mySimulation.t(`insight_fundable`));
            else if (ds.aiOverspent) insights.push(window.mySimulation.t(`insight_aileak`));
            else if (incoherent) insights.push(window.mySimulation.t(`insight_incoherent`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ratio >= this.TARGET_RATIO) insights.push(window.mySimulation.t(`insight_economics_fixed`));
            else if (ratio < 1.5) insights.push(window.mySimulation.t(`insight_economics_broken`));
            if (runway < 5) insights.push(window.mySimulation.t(`insight_runway_low`));
            if (defensible && moat >= 70) insights.push(window.mySimulation.t(`insight_moat_strong`));
            if (ds.model === this.TRUE_MODEL) insights.push(window.mySimulation.t(`insight_model_focus`));

            return {
                runway: runway,
                ratio: ratio,
                confidence: confidence,
                moat: moat,
                fundable: fundable,
                solvent: solvent,
                defensible: defensible,
                composite: composite,
                performance: performance,
                tierKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="ven-cm"><p class="ven-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="ven-cm-chip ` + (ok ? `ven-cm-ok` : `ven-cm-no`) + `">` +
                `<span class="ven-cm-ico">` + (ok ? `\u2713` : `\u2717`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="ven-cm-kpi"><div class="ven-cm-kpi-val">` + val +
                `</div><div class="ven-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="ven-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="ven-cm">` +
  `<div class="ven-cm-head">` +
    `<div class="ven-cm-score"><div class="ven-cm-score-num">` + Math.round(s.composite) +
       `<span class="ven-cm-score-den">/100</span></div>` +
       `<div class="ven-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="ven-cm-verdict"><div class="ven-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="ven-cm-verdict-tier">` + s.performance + `</div></div>` +
  `</div>` +
  `<div class="ven-cm-section"><div class="ven-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="ven-cm-chips">` + chip(!!s.fundable, t(`cm_t_fundable`)) + chip(!!s.solvent, t(`cm_t_solvent`)) +
      chip(!!s.defensible, t(`cm_t_defensible`)) + chip(!s.incoherent, t(`cm_t_coherent`)) + `</div></div>` +
  `<div class="ven-cm-section"><div class="ven-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="ven-cm-kpis">` +
      kpi(t(`col_runway`), this._fmtMonths(Number(s.runway)), t(`cm_sub_runway`)) +
      kpi(t(`col_ratio`), this._fmtRatio(Number(s.ratio)), t(`cm_sub_ratio`)) +
      kpi(t(`col_confidence`), Math.round(s.confidence), t(`cm_sub_confidence`)) +
      kpi(t(`col_moat`), Math.round(s.moat), t(`cm_sub_moat`)) +
    `</div></div>` +
  (insights ? `<div class="ven-cm-section"><div class="ven-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="ven-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
