            if (ds.runway <= 4) return window.mySimulation.t(`hint_runway`);
            if (ds.ratio < 1.5 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_economics`);
            if (ds.incoherent) return window.mySimulation.t(`hint_coherence`);
            if (state.currentPeriod >= 3 && ds.moat < 35) return window.mySimulation.t(`hint_moat`);
            if (ds.ratio >= 3.0 && ds.confidence >= 60 && ds.moat >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

